#include <iostream>

int main()
{
    // 1. Finding smallest non-unit factor using break
    int n = 35;
    int factorBreak = 2;
    while (factorBreak <= n)
    {
        if (n % factorBreak == 0)
            break;
        factorBreak++;
    }
    std::cout << "Smallest factor of " << n << " (break): " << factorBreak << "\n";

    // 2. Finding smallest non-unit factor using boolean flag
    bool found = false;
    int factorFlag = 2;
    while (factorFlag <= n && !found)
    {
        if (n % factorFlag == 0)
            found = true;
        else
            factorFlag++;
    }
    std::cout << "Smallest factor of " << n << " (flag): " << factorFlag << "\n";

    // 3. Proper while translation of a for loop with continue
    // Original for: for (int i = 0; i < 4; i++) { if (i % 3 == 0) continue; sum += i; }
    int sum = 0;
    int i = 0;
    while (i < 4)
    {
        if (i % 3 == 0)
        {
            i++; // Critical: update before continue to prevent infinite loop
            continue;
        }
        sum += i;
        i++;
    }
    std::cout << "Sum with continue: " << sum << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <string_view>

bool isPalindrome(std::string_view s)
{
    if (s.empty())
        return true;

    int low = 0;
    int high = static_cast<int>(s.length()) - 1;

    while (low < high)
    {
        if (s[low] != s[high])
        {
            return false; // Early exit equivalent to break
        }
        low++;
        high--;
    }
    return true;
}

int main()
{
    std::string test1 = "abccba";
    std::string test2 = "abca";
    std::string test3 = "radar";

    std::cout << test1 << (isPalindrome(test1) ? " is a palindrome" : " is not a palindrome") << "\n";
    std::cout << test2 << (isPalindrome(test2) ? " is a palindrome" : " is not a palindrome") << "\n";
    std::cout << test3 << (isPalindrome(test3) ? " is a palindrome" : " is not a palindrome") << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

int main()
{
    const int NUMBER_OF_PRIMES = 20; // Generate first 20 primes for demonstration
    const int NUMBER_OF_PRIMES_PER_LINE = 10;
    int count = 0;   // Count the number of prime numbers
    int number = 2;  // A number to be tested for primality

    std::cout << "The first " << NUMBER_OF_PRIMES << " prime numbers are:\n";

    // Repeatedly find prime numbers
    while (count < NUMBER_OF_PRIMES)
    {
        // Assume the number is prime
        bool isPrime = true;

        // Test if number is prime
        for (int divisor = 2; divisor <= number / 2; divisor++)
        {
            if (number % divisor == 0)
            {
                isPrime = false; // Set isPrime to false
                break;           // Exit the inner loop
            }
        }

        // Print the prime number and increase the count
        if (isPrime)
        {
            count++; // Increase the count

            if (count % NUMBER_OF_PRIMES_PER_LINE == 0)
            {
                // Print the number and advance to the new line
                std::cout << std::setw(4) << number << "\n";
            }
            else
            {
                std::cout << std::setw(4) << number << " ";
            }
        }

        // Check if the next number is prime
        number++;
    }

    return 0;
}
